-- Inserts built-in default rubrics as library rows when missing. Never overwrites.
SET lock_timeout = '5s';

INSERT INTO "Rubric" ("id", "createdAt", "updatedAt", "name", "title", "schemaJson")
SELECT gen_random_uuid()::text, NOW(), NOW(), 'thesis-driven-essay', 'Thesis-driven essay grading assistant', '{"name":"thesis-driven-essay","title":"Thesis-driven essay grading assistant","scoringScale":{"type":"weighted_1_5","minScore":1,"maxScore":5,"step":1},"rubric":{"categories":[{"key":"thesis_and_content","label":"Thesis/Content","description":"Original, defensible thesis with sustained critical thinking and meaningful deductions.","weight":0.25},{"key":"organization_and_structure","label":"Organization/Structure","description":"Purposeful structure with strong progression, clear transitions, and a conclusion that extends thinking.","weight":0.25},{"key":"evidence_and_support","label":"Evidence/Support","description":"Precise, well-integrated evidence that deepens analysis and builds authority.","weight":0.2},{"key":"voice_and_style","label":"Voice/Style","description":"Authentic voice with engaging, precise language and consistent tone.","weight":0.2},{"key":"grammar_and_mechanics","label":"Grammar/Syntax/Formatting","description":"Technical correctness and polished presentation that support clarity.","weight":0.1}]},"promptConfig":{"instructionsPreset":"legacy_thesis_driven_essay"},"outputSchema":{"responseShape":"categories_overall_comment","schemaVersion":1},"calibrationNotes":"Represents the pre-existing Yawp thesis-driven essay grading assistant path."}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM "Rubric" WHERE "name" = 'thesis-driven-essay');

INSERT INTO "Rubric" ("id", "createdAt", "updatedAt", "name", "title", "schemaJson")
SELECT gen_random_uuid()::text, NOW(), NOW(), 'class-starter-engagement', 'Class Starter engagement', '{"name":"class-starter-engagement","title":"Class Starter engagement","scoringScale":{"type":"points_scale","minScore":0,"maxScore":3},"rubric":{"categories":[{"key":"engagement","label":"Engagement","weight":1,"description":"How fully the student showed up to the writing: whether they took the prompt somewhere, stayed with their own thinking, and gave the entry real effort rather than filling the space.","scoreLabels":[{"value":0,"label":"Absent"},{"value":1,"label":"Hardly there"},{"value":2,"label":"Showed up"},{"value":3,"label":"All in"}],"feedbackEnabled":false,"grammarHighlighting":false}]},"promptConfig":{"gradingInstructions":"You are reading a Class Starter entry: a short, open-ended piece of writing done to begin class. It is low-stakes, exploratory, and effort-based.\n\nJudge one thing: engagement. Engagement is whether the student actually wrote and actually reflected. Read for whether they took the prompt somewhere of their own, stayed with a thought long enough to develop it, and gave the entry real effort — not for whether the writing is polished, and not for whether the thinking is sophisticated.\n\nWeigh substance over length. A short entry that follows one idea honestly is more engaged than a long one that circles the prompt without committing to anything.\n\nDo not grade grammar, spelling, punctuation, or formatting, and do not comment on them. Rough edges are expected here and never lower the score.\n\nThis is not a formally graded writing assignment. Do not ask the entry to be organized, to support its claims, or to build past a first response, and do not mark it up. Honest effort earns full credit.\n\nScore engagement using these words exactly:\n- 3, All in: took the prompt somewhere of their own and stayed with it; the thinking develops.\n- 2, Showed up: engaged with the prompt and did the work, without pushing past the obvious.\n- 1, Hardly there: touched the prompt but did not invest; the entry stops before it starts.\n- 0, Absent: nothing to read, or nothing that responds to the prompt.\n\nWrite the overall feedback to the student about their engagement: what they reached for, and the one thing that would take the next entry further. Keep it warm and brief."},"outputSchema":{"responseShape":"categories_overall_comment","schemaVersion":1},"calibrationNotes":"Soft, effort-based. Checks that the student wrote and reflected; honest effort earns full credit."}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM "Rubric" WHERE "name" = 'class-starter-engagement');

INSERT INTO "Rubric" ("id", "createdAt", "updatedAt", "name", "title", "schemaJson")
SELECT gen_random_uuid()::text, NOW(), NOW(), 'daily-pages-short-form', 'Daily Pages short-form writing', '{"name":"daily-pages-short-form","title":"Daily Pages short-form writing","scoringScale":{"type":"weighted_1_5","minScore":1,"maxScore":5,"step":1},"rubric":{"categories":[{"key":"depth_of_thought","label":"Depth of Thought","weight":0.3,"description":"Whether the paragraph has a point worth making — a claim, a reading, a distinction, a judgment, depending on the kind of paragraph — and whether the thinking behind it holds up. Restating the prompt is not a point, and neither is something nobody would dispute. A point that is precise and survives the objection a reader would raise first is what this reads.","scoreLabels":[{"value":1,"label":"Beginning"},{"value":2,"label":"Developing"},{"value":3,"label":"Proficient"},{"value":4,"label":"Strong"},{"value":5,"label":"Exemplary"}],"bands":[{"min":1,"max":1,"label":"Beginning","description":"Nothing to read, or nothing that engages the prompt."},{"min":2,"max":2,"label":"Developing","description":"A reaction rather than a point: agreement, disagreement, or the prompt restated."},{"min":3,"max":3,"label":"Proficient","description":"A real point with a reason behind it, both at the level anyone would reach first."},{"min":4,"max":4,"label":"Strong","description":"A precise point, with reasoning that holds against the obvious objection."},{"min":5,"max":5,"label":"Exemplary","description":"A point worth making — exact, not obvious, and held up where it is most likely to fail."}],"feedbackEnabled":true,"grammarHighlighting":false},{"key":"development_of_thought","label":"Development of Thought","weight":0.25,"description":"Whether the point is actually held up: a reason, a specific, a quotation, a case — and whether it is explained rather than only named. At this length one well-chosen specific, fully explained, beats three mentioned in passing — the test is whether a reader finishes the paragraph persuaded rather than merely informed of an opinion.","scoreLabels":[{"value":1,"label":"Beginning"},{"value":2,"label":"Developing"},{"value":3,"label":"Proficient"},{"value":4,"label":"Strong"},{"value":5,"label":"Exemplary"}],"bands":[{"min":1,"max":1,"label":"Beginning","description":"No support; a single assertion, or the same point restated."},{"min":2,"max":2,"label":"Developing","description":"Support named but never explained, or a paragraph that circles the point without backing it."},{"min":3,"max":3,"label":"Proficient","description":"One specific or reason, explained well enough to do its work."},{"min":4,"max":4,"label":"Strong","description":"Support chosen for the point it carries, explained so the point is genuinely held up."},{"min":5,"max":5,"label":"Exemplary","description":"Every sentence earns its place: the support is exact, the explanation tight, the point established in the space given."}],"feedbackEnabled":true,"grammarHighlighting":false},{"key":"organization_and_structure","label":"Organization/Structure","weight":0.12,"description":"Whether the paragraph is shaped the way its kind of paragraph should be: a point a reader can find, support in an order that makes sense, a close that lands. There is no one required form — an analysis, an argued position and a definition are built differently — but a reader should never have to hunt for what the paragraph is doing. Warm-up sentences that restate the prompt or announce what is coming are the most common way this score is lost.","scoreLabels":[{"value":1,"label":"Beginning"},{"value":2,"label":"Developing"},{"value":3,"label":"Proficient"},{"value":4,"label":"Strong"},{"value":5,"label":"Exemplary"}],"bands":[{"min":1,"max":1,"label":"Beginning","description":"No order a reader can follow."},{"min":2,"max":2,"label":"Developing","description":"The point has to be inferred; sentences come in the order they were thought of."},{"min":3,"max":3,"label":"Proficient","description":"A findable point, its support, and a close, in an order that works."},{"min":4,"max":4,"label":"Strong","description":"Built deliberately for its kind of paragraph, each sentence handing off to the next."},{"min":5,"max":5,"label":"Exemplary","description":"Shaped so the order itself carries the argument; nothing could be moved without cost."}],"feedbackEnabled":true,"grammarHighlighting":false},{"key":"voice_and_style","label":"Voice/Style","weight":0.2,"description":"Whether the prose has been edited. First person is allowed and is never an error here — first person doing work, where the student’s own experience is the evidence or the judgment is theirs to own, belongs in a top entry. What costs is unrefined writing: the hedge in front of the point (\"I think that\", \"in my opinion\"), narrating one’s own process (\"what I thought was\", \"I’m pretty sure that\"), and filler. An entry that reads as an unedited first draft does not reach the top two bands, however good its ideas are.","scoreLabels":[{"value":1,"label":"Beginning"},{"value":2,"label":"Developing"},{"value":3,"label":"Proficient"},{"value":4,"label":"Strong"},{"value":5,"label":"Exemplary"}],"bands":[{"min":1,"max":1,"label":"Beginning","description":"Flat or garbled; word choice obscures the meaning."},{"min":2,"max":2,"label":"Developing","description":"Understandable but vague or padded, with hedges standing in for the point."},{"min":3,"max":3,"label":"Proficient","description":"Clear and readable, but unedited: hedges, process narration, or filler are still in it."},{"min":4,"max":4,"label":"Strong","description":"Edited: the point is stated outright, the hedges are gone, and the words are chosen rather than reached for."},{"min":5,"max":5,"label":"Exemplary","description":"Controlled and economical throughout — prose that holds up read aloud, where any first person is there because it does work."}],"feedbackEnabled":true,"grammarHighlighting":false},{"key":"grammar_and_mechanics","label":"Grammar/Syntax/Mechanics","weight":0.13,"description":"Sentence construction, punctuation, usage, spelling, and formatting, held to the AP standard for timed writing: some errors are expected in a piece written this quickly, and they cost only when they are frequent enough to distract from meaning. Graded here — unlike a Class Starter, where it never is — and marked up, so the student can see the specific errors rather than a general note about them.","scoreLabels":[{"value":1,"label":"Beginning"},{"value":2,"label":"Developing"},{"value":3,"label":"Proficient"},{"value":4,"label":"Strong"},{"value":5,"label":"Exemplary"}],"bands":[{"min":1,"max":1,"label":"Beginning","description":"Errors throughout that block the meaning."},{"min":2,"max":2,"label":"Developing","description":"Errors frequent enough that the reader has to work past them to get the meaning."},{"min":3,"max":3,"label":"Proficient","description":"Errors a reader notices, sometimes enough to slow them down, but the meaning comes through."},{"min":4,"max":4,"label":"Strong","description":"Occasional errors that never distract from meaning."},{"min":5,"max":5,"label":"Exemplary","description":"Controlled sentences, including the harder constructions it attempts; occasional slips of the kind timed writing produces do not keep it from this band."}],"feedbackEnabled":true,"grammarHighlighting":true}]},"promptConfig":{"gradingInstructions":"You are grading a Daily Pages entry: short academic paragraph practice, graded formally. It is usually one paragraph, sometimes up to a page, written in a short, set time. Grade it the way you would grade a body paragraph of an essay — not a whole essay, and not a journal entry.\n\nThe paragraph can be of more than one kind: an analysis, an argued position, a comparison, a definition, an interpretation, an evaluation, or a synthesis. Judge it against the kind of paragraph the prompt asks for. It does not have to open with a claim, and there is no single required form — but a reader should be able to find the point and see it held up.\n\nIt is not an exploration: writing to find out what you think, with the point arriving at the end or not at all, is what a Class Starter is for, and it is not what this assignment asks for.\n\nThis is not a Class Starter and it is not graded like one. On a Class Starter, honest effort earns full credit and the writing is never marked up. Here, effort alone earns the middle of the scale. Do not give credit for showing up to the page — the question is not whether the student wrote something, it is how good the point is, how well it is held up, and how well it is written.\n\nJudge five things, and score each one separately. The first two matter most.\n\n1. Depth of Thought — is the point worth making, and does the thinking behind it hold? Depending on the kind of paragraph, the point may be a claim, a reading of a passage, a distinction, or a judgment. Restating the prompt is not a point; neither is something nobody would dispute. A first reaction is not a point either. Look for a point that is precise and survives the objection a reader raises first.\n\n2. Development of Thought — is the point actually held up? Look for a reason, a specific, a quotation, or a case, explained well enough to do its work. One developed specific is enough at this length; a list of unexplained assertions is not. If the prompt names a text or an excerpt, the support should come from it.\n\n3. Organization/Structure — is the paragraph shaped the way its kind of paragraph should be? A reader should find the point without hunting for it, the support should come in an order that makes sense, and the close should land. Do not require any one form. Mark down throat-clearing: restating the prompt, announcing what the paragraph will do, or narrating the student''s own process.\n\n4. Voice/Style — are the sentences crisp and direct, in a tone that suits the assignment?\n\n5. Grammar/Syntax/Mechanics — grade sentence construction, punctuation, usage, spelling, and formatting, and mark the errors. Grammar and syntax count in this assignment. Point to specific errors rather than describing them in general terms.\n\nScore grammar on the AP standard for timed writing. Some grammar and spelling errors are understandable in a piece written in a short, set time; they lower the score only when they are frequent enough to distract from meaning. An entry with a few scattered slips and controlled sentences can still score 5. Mark every error you find either way, so the student can see it — the standard governs the score, not what gets marked.\n\nOn first person: it is allowed, and writing \"I\" is never an error. Never mark a student down for it. First person done well belongs in a top entry — the student''s own experience as the evidence, or a judgment that is theirs to own.\n\nWhat the top of the scale requires instead is refinement. An entry that reads as an unedited first draft — hedges in front of the point (\"I think that\", \"I feel like\", \"in my opinion\"), narration of its own process (\"what I thought was\", \"I''m pretty sure that\"), filler — scores no higher than 3 in Voice/Style, however good its ideas are. The top two bands are for prose that has been edited.\n\nCoach the difference rather than deducting for a phrase: show the student their own sentence with the hedge cut, so they can see the point underneath it. The habit being taught is stating the point outright, not avoiding the first person.\n\nWeigh thinking above craft. A clean, well-ordered entry with nothing in it is not a good Daily Pages entry, and an entry with a real point and some rough sentences is not a bad one.\n\nDo not reward or penalize length on its own. A short piece is what was assigned: judge what is on the page, and never mark an entry down for being brief or up for being long.\n\nUse the bands written on each category to choose a score, then write feedback for that category: name what the student did, and the one change that would move it up a band. Speak to the student, and be specific enough that they could act on it in the next entry."},"outputSchema":{"responseShape":"categories_overall_comment","schemaVersion":1},"calibrationNotes":"A short piece graded like an essay: idea, support, structure, voice and grammar, on the essay 1-5 scale. Grammar and syntax are marked, unlike Class Starter. Effort alone earns the middle of the scale, and length is never rewarded or penalized on its own."}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM "Rubric" WHERE "name" = 'daily-pages-short-form');
